package dev.thefoolish.generated.createanotepadappthatusesa;import android.widget.*;public final class SearchActivity extends AppScreen{private LinearLayout list;protected void render(){title("Search");EditText q=field("Search documents");body.addView(q);Button go=button("Search documents");body.addView(go);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);body.addView(list);go.setOnClickListener(v->show(q.getText().toString()));show("");nav(new String[]{"Writing","Editor","Search","Library"},new Class[]{MainActivity.class,EditorActivity.class,SearchActivity.class,LibraryActivity.class});}private void show(String q){list.removeAllViews();String term=q==null?"":q.trim().toLowerCase(java.util.Locale.US);String raw=store.text("documents","");if(raw.isEmpty()){list.addView(text("No saved documents.",14,false));return;}int found=0;for(String r:raw.split("\n")){String[] x=r.split("[|]",2);if(x.length==2&&(term.isEmpty()||r.toLowerCase(java.util.Locale.US).contains(term))){list.addView(card(x[0],x[1]));found++;}}if(found==0)list.addView(text("No documents match your search.",14,false));}}